'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const DeepLink = require('../assets/deeplink.js');

// Golden URIs generated by the server reference encoder
// (TrustTunnel/deeplink and scripts/config_to_deeplink.py).
const MINIMAL_URI = 'tt://?AAECAQ92cG4uZXhhbXBsZS5jb20FBWFsaWNlBglzZWNyZXQxMjMCCzEuMi4zLjQ6NDQz';
const NAMED_URI = 'tt://?AAECAQ92cG4uZXhhbXBsZS5jb20FBWFsaWNlBglzZWNyZXQxMjMCCzEuMi4zLjQ6NDQzDAlNeSBTZXJ2ZXINEAcxLjEuMS4xBzguOC44Ljg';
const SUBSCRIPTION_ONLY_URI = 'tt://?AAECDjFodHRwczovL2FsaWNlOnMzY3JldEB2cG4uZXhhbXBsZS5jb20vc3Vic2NyaXB0aW9u';
const PREFIX_URI = 'tt://?AAECAQ9jcnAuZXhhbXBsZS5jb20FCHRlc3R1c2VyBgh0ZXN0cGFzcwIQMTAuMjAuMzAuNDA6ODQ0MwsKYWFiYmNjZGRlZQ';
const PROFILE_URI = 'tt://?AAECARNwcm9maWxlLmV4YW1wbGUuY29tBQh0ZXN0dXNlcgYIdGVzdHBhc3MCEDEwLjIwLjMwLjQwOjg0NDMQAQM';
const SUBSCRIPTION_WITH_FALLBACK_URI = 'tt://?AAECAQ92cG4uZXhhbXBsZS5jb20FBWFsaWNlBgZzM2NyZXQCCzEuMi4zLjQ6NDQzDjFodHRwczovL2FsaWNlOnMzY3JldEB2cG4uZXhhbXBsZS5jb20vc3Vic2NyaXB0aW9u';

// Shared Android/Windows client fixture. It uses the legacy tt://<payload>
// form without the query marker and has no version tag.
const LEGACY_V0_URI = 'tt://AQlsb2NhbGhvc3QFBHRlc3QGBHRlc3QCDjEyNy4wLjAuMTo0NDQzCwRhYWJiAwlsb2NhbGhvc3QIQVMwggFPMIH1oAMCAQICFGi8WMY2yFmtW2u_18hMQBa0T4VGMAoGCCqGSM49BAMCMBQxEjAQBgNVBAMMCWxvY2FsaG9zdDAeFw0yNjAxMzAwMDAwMDBaFw0yNzAxMzAwMDAwMDBaMBQxEjAQBgNVBAMMCWxvY2FsaG9zdDBZMBMGByqGSM49AgEGCCqGSM49AwEHA0IABB4ozK9KbqScCCTJ8CvTfW4W0r9OEsn4VcQswd-BbP9z-tdyfE5HT4uHLUSZRWUKfZjnRRkHWOwhp9KJhOE-LAWjJTAjMCEGA1UdEQQaMBiCCWxvY2FsaG9zdIILKi5sb2NhbGhvc3QwCgYIKoZIzj0EAwIDSQAwRgIhAO6gFBHDsgvWjPj39JNchcMF3X2ICgzycBwTyydxqpdiAiEAgybYwECuZopK1g6JX5tK0-5B3Of7n0NuPXRGSU5TtSc';

function payloadOf(uri) {
    assert.ok(uri.indexOf('tt://?') === 0, 'expected a tt://? URI');
    return uri.slice(6);
}

function bytesToPayload(bytes) {
    return Buffer.from(bytes).toString('base64url');
}

function concatBytes(chunks) {
    let length = 0;
    chunks.forEach((chunk) => {
        length += chunk.length;
    });
    const result = new Uint8Array(length);
    let offset = 0;
    chunks.forEach((chunk) => {
        result.set(chunk, offset);
        offset += chunk.length;
    });
    return result;
}

function tlv(tag, value) {
    const tagBytes = Uint8Array.from(DeepLink.encodeVarint(tag));
    const lenBytes = Uint8Array.from(DeepLink.encodeVarint(value.length));
    return concatBytes([tagBytes, lenBytes, value]);
}

function textTlv(tag, text) {
    return tlv(tag, new TextEncoder().encode(text));
}

function payloadFromTlvs(tlvs) {
    return bytesToPayload(concatBytes(tlvs));
}

function tagsOf(payload) {
    const bytes = Buffer.from(payload, 'base64url');
    const tags = [];
    let offset = 0;
    while (offset < bytes.length) {
        const tag = DeepLink.decodeVarint(bytes, offset);
        offset += tag.bytesRead;
        const length = DeepLink.decodeVarint(bytes, offset);
        offset += length.bytesRead;
        tags.push(tag.value);
        offset += length.value;
    }
    return tags;
}

function assertBytesEqual(actual, expected, message) {
    assert.ok(actual instanceof Uint8Array, message || 'expected Uint8Array');
    assert.deepEqual(Array.from(actual), Array.from(expected), message);
}

function assertConfigEqual(actual, expected) {
    assert.equal(actual.version, expected.version);
    assert.equal(actual.name, expected.name);
    assert.equal(actual.hostname, expected.hostname);
    assert.deepEqual(actual.addresses, expected.addresses);
    assert.equal(actual.custom_sni, expected.custom_sni);
    assert.equal(actual.has_ipv6, expected.has_ipv6);
    assert.equal(actual.username, expected.username);
    assert.equal(actual.password, expected.password);
    assert.equal(actual.skip_verification, expected.skip_verification);
    assert.equal(actual.upstream_protocol, expected.upstream_protocol);
    assert.equal(actual.anti_dpi, expected.anti_dpi);
    assert.equal(actual.client_random_prefix, expected.client_random_prefix);
    assert.equal(actual.client_random_auth_key, expected.client_random_auth_key);
    assert.equal(actual.tls_profile, expected.tls_profile);
    assert.equal(actual.subscription_url, expected.subscription_url);
    assert.deepEqual(actual.dns_upstreams, expected.dns_upstreams);
    if (expected.certificate_der) {
        assertBytesEqual(actual.certificate_der, expected.certificate_der);
    } else {
        assert.equal(actual.certificate_der, null);
    }
}

function minimalConfig() {
    return {
        hostname: 'vpn.example.com',
        addresses: ['1.2.3.4:443'],
        username: 'alice',
        password: 'secret123'
    };
}

function minimalDecoded() {
    return {
        version: 2,
        name: null,
        hostname: 'vpn.example.com',
        addresses: ['1.2.3.4:443'],
        custom_sni: null,
        has_ipv6: true,
        username: 'alice',
        password: 'secret123',
        skip_verification: false,
        certificate_der: null,
        upstream_protocol: 'HTTP/2',
        anti_dpi: false,
        client_random_prefix: null,
        client_random_auth_key: null,
        tls_profile: null,
        subscription_url: null,
        dns_upstreams: []
    };
}

describe('varint', () => {
    it('encodes the one-byte vectors', () => {
        assert.deepEqual(DeepLink.encodeVarint(0), [0x00]);
        assert.deepEqual(DeepLink.encodeVarint(37), [0x25]);
        assert.deepEqual(DeepLink.encodeVarint(63), [0x3f]);
    });

    it('encodes the two-byte vectors', () => {
        assert.deepEqual(DeepLink.encodeVarint(64), [0x40, 0x40]);
        assert.deepEqual(DeepLink.encodeVarint(1000), [0x43, 0xe8]);
        assert.deepEqual(DeepLink.encodeVarint(16383), [0x7f, 0xff]);
    });

    it('encodes the four-byte vectors', () => {
        assert.deepEqual(DeepLink.encodeVarint(16384), [0x80, 0x00, 0x40, 0x00]);
        assert.deepEqual(DeepLink.encodeVarint(1073741823), [0xbf, 0xff, 0xff, 0xff]);
    });

    it('rejects values above the four-byte range', () => {
        assert.throws(() => DeepLink.encodeVarint(1073741824), /Varint value too large/);
    });

    it('decodes at an offset', () => {
        const bytes = Uint8Array.from([0xff, 0x40, 0x40]);
        assert.deepEqual(DeepLink.decodeVarint(bytes, 1), { value: 64, bytesRead: 2 });
    });

    it('decodes an eight-byte value', () => {
        const bytes = Uint8Array.from([0xc0, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00]);
        assert.deepEqual(DeepLink.decodeVarint(bytes, 0), { value: 4294967296, bytesRead: 8 });
    });

    it('rejects a truncated value', () => {
        assert.throws(() => DeepLink.decodeVarint(Uint8Array.from([0x40]), 0), /Unexpected end/);
    });
});

describe('golden URIs', () => {
    it('encodes the minimal config exactly like the server reference', () => {
        assert.equal(DeepLink.encode(minimalConfig()), MINIMAL_URI);
        assertConfigEqual(DeepLink.decode(MINIMAL_URI), minimalDecoded());
    });

    it('encodes name and DNS upstreams exactly like the server reference', () => {
        const config = Object.assign(minimalConfig(), {
            name: 'My Server',
            dns_upstreams: ['1.1.1.1', '8.8.8.8']
        });
        assert.equal(DeepLink.encode(config), NAMED_URI);
        const decoded = DeepLink.decode(NAMED_URI);
        assert.equal(decoded.name, 'My Server');
        assert.deepEqual(decoded.dns_upstreams, ['1.1.1.1', '8.8.8.8']);
    });

    it('encodes a subscription-only link exactly like the server reference', () => {
        const config = { subscription_url: 'https://alice:s3cret@vpn.example.com/subscription' };
        assert.equal(DeepLink.encode(config), SUBSCRIPTION_ONLY_URI);
        const decoded = DeepLink.decode(SUBSCRIPTION_ONLY_URI);
        assert.equal(decoded.subscription_url, 'https://alice:s3cret@vpn.example.com/subscription');
        assert.equal(decoded.hostname, null);
        assert.deepEqual(decoded.addresses, []);
        assert.deepEqual(tagsOf(payloadOf(SUBSCRIPTION_ONLY_URI)), [0x00, 0x0e]);
    });

    it('encodes client_random_prefix exactly like the server reference', () => {
        const config = {
            hostname: 'crp.example.com',
            addresses: ['10.20.30.40:8443'],
            username: 'testuser',
            password: 'testpass',
            client_random_prefix: 'aabbccddee'
        };
        assert.equal(DeepLink.encode(config), PREFIX_URI);
        assert.equal(DeepLink.decode(PREFIX_URI).client_random_prefix, 'aabbccddee');
    });

    it('encodes tls_profile exactly like the server reference', () => {
        const config = {
            hostname: 'profile.example.com',
            addresses: ['10.20.30.40:8443'],
            username: 'testuser',
            password: 'testpass',
            tls_profile: DeepLink.TLS_PROFILE_FIREFOX
        };
        assert.equal(DeepLink.encode(config), PROFILE_URI);
        assert.equal(DeepLink.decode(PROFILE_URI).tls_profile, DeepLink.TLS_PROFILE_FIREFOX);
    });

    it('omits the default tls_profile', () => {
        // The QR page canonicalizes the default away; the server reference emits
        // any explicitly present tls_profile.
        const config = Object.assign(minimalConfig(), { tls_profile: DeepLink.TLS_PROFILE_CHROME });
        assert.equal(DeepLink.encode(config), MINIMAL_URI);
    });

    it('rejects an unknown tls_profile', () => {
        const config = Object.assign(minimalConfig(), { tls_profile: { id: 0x07, label: 'Future' } });
        assert.throws(() => DeepLink.encode(config), /Unsupported tls_profile/);
    });

    it('encodes a subscription URL with static fallback exactly like the server reference', () => {
        const config = {
            hostname: 'vpn.example.com',
            addresses: ['1.2.3.4:443'],
            username: 'alice',
            password: 's3cret',
            subscription_url: 'https://alice:s3cret@vpn.example.com/subscription'
        };
        assert.equal(DeepLink.encode(config), SUBSCRIPTION_WITH_FALLBACK_URI);
        const decoded = DeepLink.decode(SUBSCRIPTION_WITH_FALLBACK_URI);
        assert.equal(decoded.subscription_url, config.subscription_url);
        assert.equal(decoded.hostname, config.hostname);
        assert.deepEqual(decoded.addresses, config.addresses);
    });

    it('emits version 2 and no base64 padding', () => {
        const payload = payloadOf(MINIMAL_URI);
        assert.ok(payload.startsWith('AAEC'));
        assert.ok(payload.indexOf('=') === -1);
        assert.deepEqual(tagsOf(payload), [0x00, 0x01, 0x05, 0x06, 0x02]);
    });

    it('uses the server field order for a full configuration', () => {
        const payload = DeepLink.encodePayload({
            name: 'Full Server',
            hostname: 'vpn.example.com',
            addresses: ['1.2.3.4:443'],
            username: 'alice',
            password: 'secret',
            custom_sni: 'sni.example.org',
            has_ipv6: false,
            skip_verification: true,
            certificate_der: Uint8Array.from([0x30, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05]),
            upstream_protocol: 'HTTP/3',
            anti_dpi: true,
            client_random_prefix: 'a0b0/f0f0',
            client_random_auth_key: '00112233445566778899aabbccddeeff',
            tls_profile: DeepLink.TLS_PROFILE_FIREFOX,
            dns_upstreams: ['1.1.1.1'],
            subscription_url: 'https://alice:secret@vpn.example.com/subscription'
        });
        assert.deepEqual(tagsOf(payload), [
            0x00, 0x01, 0x05, 0x06, 0x02, 0x0b, 0x0f, 0x10, 0x03, 0x04, 0x07,
            0x0a, 0x08, 0x09, 0x0c, 0x0d, 0x0e
        ]);
    });

    it('accepts the legacy tt:// form used by the Android and Windows clients', () => {
        assert.ok(LEGACY_V0_URI.indexOf('tt://?') !== 0);
        const config = DeepLink.decode(LEGACY_V0_URI);
        assert.equal(config.version, 0);
        assert.equal(config.hostname, 'localhost');
        assert.equal(config.username, 'test');
        assert.equal(config.password, 'test');
        assert.deepEqual(config.addresses, ['127.0.0.1:4443']);
        assert.equal(config.client_random_prefix, 'aabb');
        assert.equal(config.custom_sni, 'localhost');
        assert.equal(config.has_ipv6, true);
        assert.equal(config.upstream_protocol, 'HTTP/2');
        assert.equal(config.certificate_der.length, 339);
        assert.match(DeepLink.derToPem(config.certificate_der), /^-----BEGIN CERTIFICATE-----/);
    });

    it('accepts tt://?, #tt=, tt=, and raw payload inputs', () => {
        const payload = payloadOf(MINIMAL_URI);
        const expected = DeepLink.decode(MINIMAL_URI);
        assert.deepEqual(DeepLink.decode(payload), expected);
        assert.deepEqual(DeepLink.decode('#tt=' + payload), expected);
        assert.deepEqual(DeepLink.decode('tt=' + payload), expected);
        assert.deepEqual(DeepLink.decode('  ' + MINIMAL_URI + '  '), expected);
    });
});

describe('round-trip', () => {
    const syntheticDer = Uint8Array.from([0x30, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05]);
    const fullConfig = {
        name: 'Full Server',
        hostname: 'vpn.example.com',
        addresses: ['1.2.3.4:443', '[2001:db8::1]:8443'],
        username: 'alice',
        password: 's3cr3t@:/',
        custom_sni: 'sni.example.org',
        has_ipv6: false,
        skip_verification: true,
        certificate_der: syntheticDer,
        upstream_protocol: 'HTTP/3',
        anti_dpi: true,
        client_random_prefix: 'a0b0/f0f0',
        client_random_auth_key: '00112233445566778899aabbccddeeff',
        tls_profile: DeepLink.TLS_PROFILE_FIREFOX,
        dns_upstreams: ['1.1.1.1', 'tls://dns.example.com', 'https://dns.example.com/dns-query'],
        subscription_url: 'https://alice:s3cret@vpn.example.com/subscription'
    };

    it('round-trips every field', () => {
        const decoded = DeepLink.decode(DeepLink.encode(fullConfig));
        assertConfigEqual(decoded, Object.assign({ version: 2 }, fullConfig));
    });

    it('round-trips unicode and special characters', () => {
        const config = {
            hostname: 'vpn.example.com',
            addresses: ['vpn.example.com:443'],
            username: 'пользователь',
            password: 'p@ss:word/with?chars&more=',
            name: 'Сервер №1',
            custom_sni: 'пример.рф'
        };
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.username, config.username);
        assert.equal(decoded.password, config.password);
        assert.equal(decoded.name, config.name);
        assert.equal(decoded.custom_sni, config.custom_sni);
    });

    it('round-trips long values that use two-byte lengths', () => {
        const longName = 'n'.repeat(300);
        const longDns = 'tls://' + 'd'.repeat(300) + '.example.com';
        const config = Object.assign(minimalConfig(), {
            name: longName,
            dns_upstreams: [longDns]
        });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.name, longName);
        assert.deepEqual(decoded.dns_upstreams, [longDns]);
    });

    it('round-trips multiple addresses', () => {
        const config = Object.assign(minimalConfig(), {
            addresses: ['1.2.3.4:443', '5.6.7.8:443', '[2001:db8::1]:8443']
        });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.deepEqual(decoded.addresses, config.addresses);
    });

    it('round-trips every flag combination', () => {
        for (const hasIpv6 of [true, false]) {
            for (const skipVerification of [false, true]) {
                for (const antiDpi of [false, true]) {
                    for (const protocol of ['HTTP/2', 'HTTP/3']) {
                        const config = Object.assign(minimalConfig(), {
                            has_ipv6: hasIpv6,
                            skip_verification: skipVerification,
                            anti_dpi: antiDpi,
                            upstream_protocol: protocol
                        });
                        const decoded = DeepLink.decode(DeepLink.encode(config));
                        assert.equal(decoded.has_ipv6, hasIpv6);
                        assert.equal(decoded.skip_verification, skipVerification);
                        assert.equal(decoded.anti_dpi, antiDpi);
                        assert.equal(decoded.upstream_protocol, protocol);
                    }
                }
            }
        }
    });

    it('decodes empty optional strings and omits them on re-encode', () => {
        const payload = payloadFromTlvs([
            tlv(0x00, Uint8Array.from([2])),
            textTlv(0x01, 'vpn.example.com'),
            textTlv(0x05, 'alice'),
            textTlv(0x06, 'secret'),
            textTlv(0x02, '1.2.3.4:443'),
            textTlv(0x03, ''),
            textTlv(0x0c, '')
        ]);
        const config = DeepLink.decodePayload(payload);
        assert.equal(config.custom_sni, '');
        assert.equal(config.name, '');
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.custom_sni, null);
        assert.equal(decoded.name, null);
    });

    it('omits default values', () => {
        const withDefaults = Object.assign(minimalConfig(), {
            has_ipv6: true,
            skip_verification: false,
            anti_dpi: false,
            upstream_protocol: 'HTTP/2'
        });
        assert.equal(DeepLink.encode(withDefaults), MINIMAL_URI);
        assert.deepEqual(tagsOf(payloadOf(DeepLink.encode(withDefaults))), [0x00, 0x01, 0x05, 0x06, 0x02]);
    });

    it('is deterministic', () => {
        assert.equal(DeepLink.encode(fullConfig), DeepLink.encode(fullConfig));
    });

    it('accepts protocol names and numbers', () => {
        const base = minimalConfig();
        const http3Name = DeepLink.decode(DeepLink.encode(Object.assign({}, base, { upstream_protocol: 'HTTP/3' })));
        const http3Lower = DeepLink.decode(DeepLink.encode(Object.assign({}, base, { upstream_protocol: 'http3' })));
        const http3Number = DeepLink.decode(DeepLink.encode(Object.assign({}, base, { upstream_protocol: 2 })));
        assert.equal(http3Name.upstream_protocol, 'HTTP/3');
        assert.equal(http3Lower.upstream_protocol, 'HTTP/3');
        assert.equal(http3Number.upstream_protocol, 'HTTP/3');
    });
});

describe('version handling', () => {
    const required = [
        textTlv(0x01, 'vpn.example.com'),
        textTlv(0x02, '1.2.3.4:443'),
        textTlv(0x05, 'alice'),
        textTlv(0x06, 'secret')
    ];

    it('accepts a version 0 link without a version tag', () => {
        const config = DeepLink.decodePayload(payloadFromTlvs(required));
        assert.equal(config.version, 0);
        assert.equal(config.hostname, 'vpn.example.com');
    });

    it('accepts version 1 links', () => {
        const config = DeepLink.decodePayload(payloadFromTlvs([tlv(0x00, Uint8Array.from([1]))].concat(required)));
        assert.equal(config.version, 1);
        assert.equal(config.username, 'alice');
    });

    it('accepts version 2 links', () => {
        const config = DeepLink.decodePayload(payloadFromTlvs([tlv(0x00, Uint8Array.from([2]))].concat(required)));
        assert.equal(config.version, 2);
    });

    it('rejects version 3 links', () => {
        assert.throws(
            () => DeepLink.decodePayload(payloadFromTlvs([tlv(0x00, Uint8Array.from([3]))].concat(required))),
            /version 3.*supports version 2/
        );
    });

    it('always writes version 2', () => {
        const config = DeepLink.decode(MINIMAL_URI);
        assert.equal(config.version, 2);
        assert.equal(payloadOf(DeepLink.encode(config)).slice(0, 4), 'AAEC');
    });
});

describe('required fields and subscription URL', () => {
    it('rejects a link without a hostname', () => {
        assert.throws(() => DeepLink.encode({ addresses: ['1.2.3.4:443'], username: 'a', password: 'b' }), /hostname/);
    });

    it('rejects a link without an address', () => {
        assert.throws(() => DeepLink.encode({ hostname: 'vpn.example.com', username: 'a', password: 'b' }), /addresses/);
    });

    it('rejects a link without a username', () => {
        assert.throws(() => DeepLink.encode({ hostname: 'vpn.example.com', addresses: ['1.2.3.4:443'], password: 'b' }), /username/);
    });

    it('rejects a link without a password', () => {
        assert.throws(() => DeepLink.encode({ hostname: 'vpn.example.com', addresses: ['1.2.3.4:443'], username: 'a' }), /password/);
    });

    it('does not require static fields for a subscription-only link', () => {
        const decoded = DeepLink.decode(SUBSCRIPTION_ONLY_URI);
        assert.equal(decoded.hostname, null);
        assert.deepEqual(decoded.addresses, []);
        assert.equal(decoded.username, null);
        assert.equal(decoded.password, null);
    });

    it('keeps static fallback fields next to a subscription URL', () => {
        const config = Object.assign(minimalConfig(), {
            subscription_url: 'https://alice:secret@vpn.example.com/subscription'
        });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.subscription_url, config.subscription_url);
        assert.equal(decoded.hostname, config.hostname);
        assert.deepEqual(decoded.addresses, config.addresses);
        assert.equal(decoded.username, config.username);
    });

    it('replaces the subscription URL in a subscription-only link', () => {
        const before = DeepLink.decode(SUBSCRIPTION_ONLY_URI);
        const nextUrl = 'https://bob:newsecret@vpn.example.com/new-subscription';
        const after = DeepLink.decode(DeepLink.encode(Object.assign({}, before, { subscription_url: nextUrl })));
        assert.equal(after.subscription_url, nextUrl);
        assert.equal(after.hostname, null);
        assert.deepEqual(after.addresses, []);
        assert.deepEqual(tagsOf(DeepLink.encodePayload(Object.assign({}, before, { subscription_url: nextUrl }))), [0x00, 0x0e]);
    });

    it('replaces the subscription URL and keeps static fallback fields', () => {
        const before = DeepLink.decode(SUBSCRIPTION_WITH_FALLBACK_URI);
        const nextUrl = 'https://bob:newsecret@vpn.example.com/new-subscription';
        const after = DeepLink.decode(DeepLink.encode(Object.assign({}, before, { subscription_url: nextUrl })));
        assert.equal(after.subscription_url, nextUrl);
        assert.equal(after.hostname, before.hostname);
        assert.deepEqual(after.addresses, before.addresses);
        assert.equal(after.username, before.username);
    });

    it('requires static fields when the subscription URL is removed', () => {
        assert.throws(() => DeepLink.encode({ subscription_url: null }), /hostname/);
    });

    it('rejects a non-https subscription URL on encode', () => {
        assert.throws(
            () => DeepLink.encode({ subscription_url: 'http://vpn.example.com/subscription' }),
            /must start with https:\/\//
        );
    });

    it('rejects a non-https subscription URL on decode', () => {
        const payload = payloadFromTlvs([
            tlv(0x00, Uint8Array.from([2])),
            textTlv(0x0e, 'http://vpn.example.com/subscription')
        ]);
        assert.throws(() => DeepLink.decodePayload(payload), /must start with https:\/\//);
    });
});

describe('client random fields', () => {
    it('accepts a prefix and a prefix with mask', () => {
        assert.equal(DeepLink.validateClientRandomPrefix('a0b0'), null);
        assert.equal(DeepLink.validateClientRandomPrefix('a0b0/f0f0'), null);
        assert.equal(DeepLink.validateClientRandomPrefix('A0B0/F0F0'), null);
        assert.equal(DeepLink.validateClientRandomPrefix('a0b0/'), null);
    });

    it('rejects invalid prefixes and masks', () => {
        assert.match(DeepLink.validateClientRandomPrefix('zz'), /hexadecimal/);
        assert.match(DeepLink.validateClientRandomPrefix('abc'), /even number/);
        assert.match(DeepLink.validateClientRandomPrefix('a0b0/f0f0/1'), /prefix or prefix\/mask/);
        assert.match(DeepLink.validateClientRandomPrefix('a0b0/zz'), /mask must contain only hexadecimal/);
        assert.match(DeepLink.validateClientRandomPrefix('a0b0/f'), /mask must have an even number/);
    });

    it('accepts and rejects auth keys', () => {
        assert.equal(DeepLink.validateHexKey('00112233445566778899aabbccddeeff', 'key'), null);
        assert.match(DeepLink.validateHexKey('zz', 'key'), /hexadecimal/);
        assert.match(DeepLink.validateHexKey('0', 'key'), /even number/);
        assert.match(DeepLink.validateHexKey('', 'key'), /hexadecimal/);
    });

    it('round-trips a prefix with a mask', () => {
        const config = Object.assign(minimalConfig(), { client_random_prefix: 'a0b0/f0f0' });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.client_random_prefix, 'a0b0/f0f0');
    });

    it('round-trips an auth key', () => {
        const config = Object.assign(minimalConfig(), {
            client_random_auth_key: '00112233445566778899aabbccddeeff'
        });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.client_random_auth_key, config.client_random_auth_key);
        assert.deepEqual(tagsOf(payloadOf(DeepLink.encode(config))), [0x00, 0x01, 0x05, 0x06, 0x02, 0x0f]);
    });

    it('keeps both fields when both are present', () => {
        const config = Object.assign(minimalConfig(), {
            client_random_prefix: 'a0b0',
            client_random_auth_key: '00112233445566778899aabbccddeeff'
        });
        const decoded = DeepLink.decode(DeepLink.encode(config));
        assert.equal(decoded.client_random_prefix, 'a0b0');
        assert.equal(decoded.client_random_auth_key, config.client_random_auth_key);
    });

    it('rejects an invalid prefix on encode and decode', () => {
        assert.throws(
            () => DeepLink.encode(Object.assign(minimalConfig(), { client_random_prefix: 'zz' })),
            /prefix must contain only hexadecimal/
        );
        const payload = payloadFromTlvs([
            tlv(0x00, Uint8Array.from([2])),
            textTlv(0x01, 'vpn.example.com'),
            textTlv(0x05, 'alice'),
            textTlv(0x06, 'secret'),
            textTlv(0x02, '1.2.3.4:443'),
            textTlv(0x0b, 'zz')
        ]);
        assert.throws(() => DeepLink.decodePayload(payload), /prefix must contain only hexadecimal/);
    });

    it('rejects an invalid auth key on decode', () => {
        const payload = payloadFromTlvs([
            tlv(0x00, Uint8Array.from([2])),
            textTlv(0x01, 'vpn.example.com'),
            textTlv(0x05, 'alice'),
            textTlv(0x06, 'secret'),
            textTlv(0x02, '1.2.3.4:443'),
            textTlv(0x0f, 'nothex')
        ]);
        assert.throws(() => DeepLink.decodePayload(payload), /auth key must contain only hexadecimal/);
    });
});

describe('certificate helpers', () => {
    it('round-trips a single synthetic DER certificate', () => {
        const der = Uint8Array.from([0x30, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05]);
        const pem = DeepLink.derToPem(der);
        assert.match(pem, /^-----BEGIN CERTIFICATE-----/);
        assertBytesEqual(DeepLink.pemToDer(pem), der);
    });

    it('round-trips a multi-certificate DER chain', () => {
        const cert1 = Uint8Array.from([0x30, 0x03, 0x01, 0x02, 0x03]);
        const cert2 = Uint8Array.from([0x30, 0x04, 0x04, 0x05, 0x06, 0x07]);
        const der = concatBytes([cert1, cert2]);
        const pem = DeepLink.derToPem(der);
        assert.equal((pem.match(/-----BEGIN CERTIFICATE-----/g) || []).length, 2);
        assertBytesEqual(DeepLink.pemToDer(pem), der);
    });

    it('handles long-form DER lengths', () => {
        const der = Uint8Array.from([0x30, 0x81, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05]);
        const pem = DeepLink.derToPem(der);
        assertBytesEqual(DeepLink.pemToDer(pem), der);
    });

    it('rejects invalid DER data', () => {
        assert.throws(() => DeepLink.derToPem(Uint8Array.from([0x31, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05])), /Invalid DER/);
        assert.throws(() => DeepLink.derToPem(Uint8Array.from([0x30, 0x0a, 0x01, 0x02, 0x03, 0x04, 0x05])), /Invalid DER/);
    });

    it('rejects empty and invalid PEM data', () => {
        assert.throws(() => DeepLink.pemToDer(''), /No valid PEM/);
        assert.throws(() => DeepLink.pemToDer('not a certificate'), /No valid PEM/);
    });

    it('round-trips the certificate from the client fixture', () => {
        const config = DeepLink.decode(LEGACY_V0_URI);
        const pem = DeepLink.derToPem(config.certificate_der);
        assertBytesEqual(DeepLink.pemToDer(pem), config.certificate_der);
    });
});

describe('malformed payloads', () => {
    const required = [
        textTlv(0x01, 'vpn.example.com'),
        textTlv(0x02, '1.2.3.4:443'),
        textTlv(0x05, 'alice'),
        textTlv(0x06, 'secret')
    ];

    it('ignores unknown tags', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x11, Uint8Array.from([1, 2, 3]))])
        );
        const config = DeepLink.decodePayload(payload);
        assert.equal(config.hostname, 'vpn.example.com');
    });

    it('rejects an unknown tls_profile byte', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x10, Uint8Array.from([0x07]))])
        );
        assert.throws(() => DeepLink.decodePayload(payload), /Unknown tls_profile/);
    });

    it('rejects a tls_profile with the wrong length', () => {
        const empty = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x10, new Uint8Array([]))])
        );
        assert.throws(() => DeepLink.decodePayload(empty), /Invalid tls_profile/);

        const long = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x10, Uint8Array.from([0x03, 0x03]))])
        );
        assert.throws(() => DeepLink.decodePayload(long), /Invalid tls_profile/);
    });

    it('rejects a TLV value that exceeds the buffer', () => {
        const payload = bytesToPayload(Uint8Array.from([0x01, 0x0a, 0x01, 0x02, 0x03]));
        assert.throws(() => DeepLink.decodePayload(payload), /exceeds buffer/);
    });

    it('rejects an invalid boolean value', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x04, Uint8Array.from([0x02]))])
        );
        assert.throws(() => DeepLink.decodePayload(payload), /Invalid has_ipv6/);
    });

    it('rejects a boolean with the wrong length', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x04, Uint8Array.from([0x00, 0x01]))])
        );
        assert.throws(() => DeepLink.decodePayload(payload), /Invalid has_ipv6/);
    });

    it('rejects an invalid protocol value', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x09, Uint8Array.from([0x03]))])
        );
        assert.throws(() => DeepLink.decodePayload(payload), /Invalid upstream_protocol/);
    });

    it('rejects a truncated DNS entry', () => {
        const payload = payloadFromTlvs(
            [tlv(0x00, Uint8Array.from([2]))].concat(required, [tlv(0x0d, Uint8Array.from([0x0a, 0x41]))])
        );
        assert.throws(() => DeepLink.decodePayload(payload), /dns_upstreams entry exceeds buffer/);
    });

    it('rejects invalid base64 and empty payloads', () => {
        assert.throws(() => DeepLink.decodePayload('%%%'));
        assert.throws(() => DeepLink.decodePayload(''), /does not contain/);
        assert.throws(() => DeepLink.decode('tt://'), /does not contain/);
    });
});

describe('client fixture compatibility', () => {
    it('re-encodes the legacy client fixture without data loss', () => {
        const before = DeepLink.decode(LEGACY_V0_URI);
        const after = DeepLink.decode(DeepLink.encode(before));
        assert.equal(after.version, 2);
        assert.equal(after.hostname, before.hostname);
        assert.equal(after.username, before.username);
        assert.equal(after.password, before.password);
        assert.deepEqual(after.addresses, before.addresses);
        assert.equal(after.client_random_prefix, before.client_random_prefix);
        assert.equal(after.custom_sni, before.custom_sni);
        assert.equal(after.has_ipv6, before.has_ipv6);
        assert.equal(after.upstream_protocol, before.upstream_protocol);
        assertBytesEqual(after.certificate_der, before.certificate_der);
    });
});
